package visualverify
import("encoding/json";"fmt";"os";"path/filepath";"github.com/LuigiD5555/origami/internal/lab/renderer")
type Verification struct{PNGSHA256 string;PixelSHA256 string;Width int;Height int;PNGBytes int}
func Verify(runDir string)(Verification,error){metaBytes,err:=os.ReadFile(filepath.Join(runDir,"render.json"));if err!=nil{return Verification{},err};var meta renderer.Result;if err:=json.Unmarshal(metaBytes,&meta);err!=nil{return Verification{},fmt.Errorf("render metadata: %w",err)};if meta.Schema!=renderer.ResultSchemaV1{return Verification{},fmt.Errorf("render metadata: unsupported schema %q",meta.Schema)};pngPath:=filepath.Join(runDir,filepath.FromSlash(meta.ImagePath));pngBytes,err:=os.ReadFile(pngPath);if err!=nil{return Verification{},err};if got:=renderer.PNGHash(pngBytes);got!=meta.PNGSHA256{return Verification{},fmt.Errorf("visual verify: png sha mismatch got=%s want=%s",got,meta.PNGSHA256)};if len(pngBytes)!=meta.PNGBytes{return Verification{},fmt.Errorf("visual verify: png byte length mismatch")};img,err:=renderer.DecodePNG(pngBytes);if err!=nil{return Verification{},err};b:=img.Bounds();if b.Dx()!=meta.Width||b.Dy()!=meta.Height{return Verification{},fmt.Errorf("visual verify: dimensions mismatch")};if got:=renderer.PixelHash(img);got!=meta.PixelSHA256{return Verification{},fmt.Errorf("visual verify: pixel sha mismatch")};return Verification{PNGSHA256:meta.PNGSHA256,PixelSHA256:meta.PixelSHA256,Width:meta.Width,Height:meta.Height,PNGBytes:meta.PNGBytes},nil}
